                      "attrs": {
                        "localId": "206d61da5514"
                      }
                    }
                  ]
                }
              ],
              "attrs": {
                "localId": "8cd88280d671"
              }
            },
            {
              "type": "paragraph",
              "content": [
                {
                  "type": "text",
                  "text": "AC2. Both Baskets Have Different Items — Combined Display",
