              ],
              "attrs": {
                "localId": "333f922fd901"
              }
            },
            {
              "type": "bulletList",
              "content": [
                {
                  "type": "listItem",
                  "attrs": {
                    "localId": "ee8ccda18dff"
                  },
                  "content": [
                    {
                      "type": "paragraph",
                      "content": [
                        {
                          "type": "text",
                          "text": "Given a Guest Shopper has no items in their cart and signs in to an account that has items, when sign-in completes, then the authenticated basket items are displayed in the cart unchanged with no items added or removed."
                        }
