                    }
                  ]
                }
              ],
              "attrs": {
                "localId": "1654eb2860e6"
              }
            },
            {
              "type": "paragraph",
              "content": [
                {
                  "type": "text",
                  "text": "AC4. Same SKU in Both Baskets — Quantities Combined",
                  "marks": [
                    {
                      "type": "strong"
                    }
                  ]
                }
              ],
              "attrs": {
                "localId": "5799f6c43d2b"
