            },
            {
              "type": "paragraph",
              "content": [
                {
                  "type": "text",
                  "text": "AC6. Merge Trigger — Any Sign-In Event",
                  "marks": [
                    {
                      "type": "strong"
                    }
                  ]
                }
              ],
              "attrs": {
                "localId": "d2809e22f548"
              }
            },
            {
              "type": "bulletList",
              "content": [
                {
