file.content:
import { FONT_MEDIUM } from '../foundation/fonts';

// Extends the base Header theme (node_modules/.../theme/components/project/header.js).
// Parts not listed here inherit base styles unchanged.
export const Header = {
  parts: [
    'container',
    'content',
    'searchContainer',
    'bodyContainer',
    'logo',
    'icons',
    'agentIcon',
    'wishlistIcon',
    'accountIcon',
    'arrowDown',
    'signout',
    'signoutIcon',
    'signoutText',
    // Zimmermann additions:
    'topBar',
    'logoBar',
    'logoButton',
    'desktopActionButton',
  ],
  baseStyle: {
    container: {
      position: 'sticky',
      top: 0,
      zIndex: 'sticky',
      backgroundColor: 'white',
      boxShadow: 'none',
      // No border — prototype header has no border/shadow
    },
    content: {
      paddingTop: 0,
      paddingBottom: 0,
    },
    bodyContainer: {
      // Un-do the base theme's flex: '1' so the nav takes natural width only,
      // letting topBar's space-between push Account/Saved/Bag to the right edge
      flex: 'none',
    },
    topBar: {
      justifyContent: 'space-between',
      alignItems: 'center',
      // Prototype: padding-top: 45px on top-row, no border
      paddingTop: 10,
      paddingBottom: 5,
    },
    logoBar: {
      alignItems: 'center',
      paddingTop: [2, 2, 4],
      paddingBottom: [10, 10, 12],
    },
    logoButton: {
      display: 'flex',
      alignItems: 'center',
      height: 'auto',
      minWidth: 'auto',
      padding: 0,
      _focus: { boxShadow: 'outline' },
      _focusVisible: { outline: 0 },
    },
    logo: {
      // Aspect ratio 631:74. Both dimensions use min() so they scale together:
      // width caps at 597px (= 70 × 631/74), height caps at 70px (= 60vw × 74/631 = 7.04vw).
      width: 'min(597px, 60vw)',
      height: 'min(70px, 7.04vw)',
    },
    desktopActionButton: {
      fontFamily: FONT_MEDIUM,
      fontSize: '12px',
      fontWeight: '500',
      letterSpacing: '0.02em',
      color: 'brand.nearBlack',
      height: 'auto',
      minWidth: 'auto',
      padding: 0,
      paddingBottom: '2px',
      position: 'relative',
      // Slide-in underline on hover — matches prototype's ::after scaleX animation
      _after: {
        content: '""',
        position: 'absolute',
        bottom: 0,
        left: 0,
        width: '100%',
        height: '1px',
        background: 'currentColor',
        transform: 'scaleX(0)',
        transformOrigin: 'right center',
        transition: 'transform 0.25s ease',
      },
      _hover: {
        _after: {
          transform: 'scaleX(1)',
          transformOrigin: 'left center',
        },
      },
    },
  },
};
